import { Option } from 'typescript-interfaces';

interface Option {
  id: string;
  value: string;
}

const InputComponent = () => {
  const [input, setInput] = useState<string>('');
  const [options, setOptions] = useState<Option[]>([
    { id: 'default', value: '' },
    { id: 'option1', value: 'Option 1' },
    { id: 'option2', value: 'Option 2' },
    { id: 'option3', value: 'Option 3' },
    // Add more options as needed
  ]);

  const isValid = /^\d+$/.test(input);

  const filteredOptions = options.filter(option => option.value === input);

  return (
    <div className="flex gap-2">
      <input
        type="text"
        value={input}
        onChange={(e) => setInput(e.target.value)}
        invalid={!isValid}
        className={`border rounded-md px-4 py-2 focus:outline-none ${!isValid ? 'border-red-500' : ''}`}
        placeholder="Enter a value..."
      />
      {filteredOptions.length > 0 && (
        <select
          value={input}
          onChange={(e) => setInput(e.target.value)}
          className="bg-gray-100 rounded-md px-4 py-2 focus:outline-none shadow-sm"
        >
          {filteredOptions.map(option => (
            <option key={option.id} value={option.value}>
              {option.id}
            </option>
          ))}
        </select>
      )}
    </div>
  );
};

export default InputComponent;
```

