  const [value, setValue] = useState<string | null>(null);
  const [options, setOptions] = useState<Option[]>([] as Option[]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setValue(prev => (prev === null ? '' : prev));
    const filtered = options.filter(option => option.id === value);
    setOptions(filtered);
  };

  const getOptions = (v: string) => {
    return options.filter(option => option.id === v);
  };

  useEffect(() => {
    // Initial data setup
    setOptions([
      { id: '1', text: 'Option 1' },
      { id: '2', text: 'Option 2' },
      { id: '3', text: 'Option 3' },
      { id: '4', text: 'Option 4' },
      { id: '5', text: 'Option 5' },
    ]);
  }, []);

  if (!value) {
    return (
      <form onSubmit={handleSubmit} className="mt-4">
        <input
          type="text"
          value={value}
          onChange={(e) => setValue(e.target.value)}
          className="invalid" // Will be overridden by actual value
          placeholder="Enter value..."
        />
      </form>
    );
  }

  const isValueValid = () => {
    return options.some(option => option.id === value);
  };

  return (
    <form onSubmit={handleSubmit} className="mt-4">
      <input
        type="text"
        value={value}
        onChange={(e) => setValue(e.target.value)}
